mapper.update:
UPDATE oc_order_item
SET refunding_qty = refunding_qty + #{qty},
    refunding_amount = refunding_amount + #{amount}
WHERE id = #{id}
  AND del_flag = '0'

UPDATE oc_order_item
SET refunding_qty = refunding_qty - #{qty},
    refunding_amount = refunding_amount - #{amount}
WHERE id = #{id}
  AND del_flag = '0'
  AND refunding_qty >= #{qty}

UPDATE oc_order_item
SET refunding_qty = refunding_qty - #{qty},
    refunding_amount = refunding_amount - #{amount},
    refunded_qty = refunded_qty + #{qty},
    refunded_amount = refunded_amount + #{amount}
WHERE id = #{id}
  AND del_flag = '0'
  AND refunding_qty >= #{qty}

UPDATE oc_order_item
SET refunded_qty = refunded_qty + #{qty},
    refunded_amount = refunded_amount + #{amount}
WHERE id = #{id}
  AND del_flag = '0'
